package safety

import(
 "context";"os";"path/filepath";"testing"
 "github.com/jackc/pgx/v5/pgxpool"
)
func TestSafetyLifecycle(t *testing.T){url:=os.Getenv("TEST_DATABASE_URL");if url==""{t.Skip("TEST_DATABASE_URL is not set")};ctx:=context.Background();pool,e:=pgxpool.New(ctx,url);if e!=nil{t.Fatal(e)};defer pool.Close();for _,name:=range []string{"0001_core.sql","0009_trust_safety.sql","0010_platform_safety_subject.sql"}{body,e:=os.ReadFile(filepath.Join("..","..","migrations",name));if e!=nil{t.Fatal(e)};if _,e=pool.Exec(ctx,string(body));e!=nil{t.Fatalf("apply %s: %v",name,e)}};_,_=pool.Exec(ctx,`TRUNCATE safety_appeals,safety_decisions,safety_reports,outbox_events CASCADE`);svc,e:=New(ctx,url);if e!=nil{t.Fatal(e)};defer svc.Close();r,e:=svc.Create(ctx,"reporter-1","platform","general","child_safety","unsafe contact request");if e!=nil{t.Fatal(e)};if r.Severity!="high"||r.Status!="submitted"{t.Fatalf("report=%+v",r)};mine,e:=svc.Mine(ctx,"reporter-1");if e!=nil||len(mine)!=1{t.Fatalf("mine=%v err=%v",mine,e)};decided,e:=svc.Decide(ctx,r.ID,"reviewer-1","triage","specialist review required");if e!=nil{t.Fatal(e)};if decided.Status!="triaged"{t.Fatalf("status=%s",decided.Status)};a,e:=svc.Appeal(ctx,r.ID,"subject-1","decision needs reconsideration");if e!=nil{t.Fatal(e)};if a.Status!="submitted"{t.Fatalf("appeal=%+v",a)};queue,e:=svc.Queue(ctx);if e!=nil||len(queue)!=1||queue[0].Status!="appealed"{t.Fatalf("queue=%v err=%v",queue,e)};var events int;if e=pool.QueryRow(ctx,`SELECT count(*) FROM outbox_events WHERE aggregate_type='safety_report'`).Scan(&events);e!=nil{t.Fatal(e)};if events!=3{t.Fatalf("events=%d",events)} }
